export const source = "'use client';\n\nimport { useState } from 'react';\n\nimport { Button } from '@/components/button/button';\nimport {\n  DropdownMenu,\n  DropdownMenuContent,\n  DropdownMenuLabel,\n  DropdownMenuRadioGroup,\n  DropdownMenuRadioItem,\n  DropdownMenuSeparator,\n  DropdownMenuTrigger,\n} from '@/components/dropdown-menu/dropdown-menu';\n\nconst POSITIONS = [\n  { value: 'top', label: 'Top' },\n  { value: 'bottom', label: 'Bottom' },\n  { value: 'right', label: 'Right' },\n];\n\nexport default function DropdownMenuRadioItems() {\n  const [position, setPosition] = useState('bottom');\n  const selected = POSITIONS.find((option) => option.value === position);\n\n  return (\n    <DropdownMenu>\n      <DropdownMenuTrigger asChild>\n        <Button variant=\"outline\">Panel: {selected?.label}</Button>\n      </DropdownMenuTrigger>\n      <DropdownMenuContent className=\"nx:w-56\">\n        <DropdownMenuLabel>Panel position</DropdownMenuLabel>\n        <DropdownMenuSeparator />\n        <DropdownMenuRadioGroup value={position} onValueChange={setPosition}>\n          {POSITIONS.map(({ value, label }) => (\n            <DropdownMenuRadioItem key={value} value={value}>\n              {label}\n            </DropdownMenuRadioItem>\n          ))}\n        </DropdownMenuRadioGroup>\n      </DropdownMenuContent>\n    </DropdownMenu>\n  );\n}\n";
